prompt --application/shared_components/logic/application_processes/set_contexts
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(369298555626252879)
,p_process_sequence=>1
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_CONTEXTS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_schema_name       varchar2(30);',
'begin',
'   --',
'   :g_cma_app_alias := v(''APP_ALIAS'');',
'   --',
'   select schema_name',
'   into   l_schema_name',
'   from   cm.cmapp',
'   where  app_alias = :g_cma_app_alias;',
'   --',
'   cm.cm_util.set_context',
'   (p_context => ''schema_name''',
'   ,p_value => l_schema_name',
'   );',
'   --',
'   cm.cm_util.set_context',
'   (p_context => ''tenant''',
'   ,p_value   => v(''P0_TENANT'')    ',
'   );',
'   --',
