prompt --application/shared_components/logic/application_processes/p0_hdr_items
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(169066964598605852)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P0_HDR_ITEMS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':p0_hdr_app_page_has_breadcrumb := ''y'';',
'--',
'if :app_page_id = 1 then',
'   --',
'   select label||'' home page''',
'   ,      icon',
'   ,      ''fa''',
'   into   :p0_hdr_page_title',
'   ,      :p0_hdr_page_icon',
'   ,      :p0_hdr_page_icon_class',
'   from   cm.cmapp',
'   where  app_alias = :app_alias;',
'else',
'   select page_title ',
'   into   :p0_hdr_page_title',
'   from   apex_application_pages',
'   where  page_id = :app_page_id ',
'   and    application_id = :app_id;',
'   --',
'   select icon',
'   ,      icon_class',
'   into   :p0_hdr_page_icon',
'   ,      :p0_hdr_page_icon_class',
'   from',
'   (',
'      select entry_target page',
'      ,      entry_image  icon',
'      ,      case',
'             when entry_image like ''%fa6%'' then',
'                  ''fa6''',
'             else',
'                  ''fa''',
'             end icon_class',
'      ,      instr(entry_target,'':'')+1  pos1',
'      ,      instr(entry_target,'':'',1,2) pos2',
'      from   apex_application_list_entries',
'      where  application_id = :APP_ID',
'      and    list_name = ''Desktop Navigation Menu''',
'   )',
'   where substr(page, pos1, pos2-pos1) = :app_page_id;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'cm.cm_public.app_page_has_breadcrumb = ''y'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_version_scn=>1
);
end;
