prompt --application/shared_components/logic/application_processes/get_job_details
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(21775595409781743)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_JOB_DETAILS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'	l_meds_job_number	number;',
'    l_data_type	        varchar2(50);',
'    l_job_data_type	    char(1);',
'    l_job_type_number   number;   ',
'    l_status            varchar2(16);',
'    l_assigned          varchar2(64);',
'    l_meic_number       number;',
'    l_supplier          varchar2(64);',
'begin',
'	l_meds_job_number := apex_util.get_session_state(''P''||:app_page_id||''_MEDS_JOB_NUMBER'');',
'	',
'    select',
'       a.data_type',
'    ,  b.job_data_type',
'    ,  b.job_type_number',
'    ,  b.status',
'    ,  b.assigned',
'    ,  b.meic_number',
'    ,  b.supplier',
'    into',
'       l_data_type',
'    ,  l_job_data_type',
'    ,  l_job_type_number',
'    ,  l_status',
'    ,  l_assigned',
'    ,  l_meic_number',
'    ,  l_supplier',
'    from meds_processing_job   a',
'    inner join job_tracking    b',
'       on b.meic_number  = a.meic_number',
'    where a.job_number   = l_meds_job_number;',
'	',
'	apex_util.set_session_state(''P''||:app_page_id||''_DATA_TYPE'',l_data_type);',
'	apex_util.set_session_state(''P''||:app_page_id||''_JOB_DATA_TYPE'',l_job_data_type);',
'	apex_util.set_session_state(''P''||:app_page_id||''_JOB_TYPE_NUMBER'',l_job_type_number);',
'	apex_util.set_session_state(''P''||:app_page_id||''_JOB_STATUS'',l_status);',
'	apex_util.set_session_state(''P''||:app_page_id||''_ASSIGNED'',l_assigned);',
'	apex_util.set_session_state(''P''||:app_page_id||''_MEIC_NUMBER'',l_meic_number);',
'	apex_util.set_session_state(''P''||:app_page_id||''_SHIP'',l_supplier);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>41379680036960
);
end;
