prompt --application/shared_components/logic/application_computations/p0_tourtype
begin
wwv_flow_imp_shared.create_flow_computation(
 p_id=>wwv_flow_imp.id(296059602486979780)
,p_computation_sequence=>10
,p_computation_item=>'P0_TOURTYPE'
,p_computation_point=>'AFTER_HEADER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation_processed=>'REPLACE_EXISTING'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l         varchar2(30);',
'begin',
'   --',
'   begin',
'      --   ',
'      select case',
'             when a.page_mode = ''Normal'' then',
'                  ''normal''',
'             else',
'                  ''dialog''',
'             end     ',
'      into   l            ',
'      from   apex_application_pages        a',
'      ,      apex_application_page_da_acts b',
'      where  a.workspace      = :g_workspace',
'      and    a.application_id = :app_id',
'      and    a.page_id        = :app_page_id',
'      and    b.workspace      = a.workspace',
'      and    b.application_id = a.application_id',
'      and    b.page_id        = a.page_id',
'      and    b.action_name    = ''GuidedTour (New Instance)''',
'      and    rownum           < 2;',
'      --',
'   exception',
'   when no_data_found then',
'      null;',
'   end;',
'   --',
'   return nvl(l,''none'');',
'   --',
'end;',
''))
,p_version_scn=>1
);
end;
