prompt --application/shared_components/logic/application_computations/g_model
begin
wwv_flow_imp_shared.create_flow_computation(
 p_id=>wwv_flow_imp.id(148441267549737244)
,p_computation_sequence=>60
,p_computation_item=>'G_MODEL'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation_processed=>'REPLACE_EXISTING'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_is_valid          number;',
'   l_model             number;',
'begin',
'   --',
'   l_model := apex_util.get_preference',
'                   (p_preference => :APP_ALIAS||''_MODEL''',
'                   ,p_user       => :APP_USER ',
'                   );',
'   --',
'   if l_model is not null then ',
'      -- check preference is valid...',
'      begin',
'          select 1',
'         into   l_is_valid',
'         from   model a',
'         where a.tenant      = :g_tenant',
'         and   a.model       = l_model;',
'         select 1',
'         into   l_is_valid',
'         from',
'         (',
'            select 1',
'            from   dual',
'            where  cm.cmuser_tool.is_tenant_admin',
'                   (p_username  => :APP_USER ',
'                   ,p_tenant    => :g_tenant',
'                   ) > 0',
'            union  all',
'            select 1',
'            from   cm.v_my_role a',
'            ,      model b',
'            where  a.cmapp_alias = :APP_ALIAS',
'            and    a.seq         = l_model ',
'            and    rownum < 2',
'         )',
'         where  rownum < 2;',
'         --',
'      exception',
'      when no_data_found then',
'         l_model := null;',
'      end;      ',
'      -- ',
'   end if;',
'   --',
'   return l_model ;',
'   --',
'end;',
''))
,p_compute_when_type=>'NEVER'
,p_version_scn=>1
);
end;
