'Y - New Tab<br>',
'N - Save to DB using PL/SQL code'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(21002952539392275789)
,p_plugin_id=>wwv_flow_imp.id(21000231306323900363)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'PLSQL Code'
,p_attribute_type=>'PLSQL'
,p_is_required=>true
,p_default_value=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  --',
'  l_collection_name VARCHAR2(100);',
'  l_blob            BLOB;',
'  l_filename        VARCHAR2(100);',
'  l_mime_type       VARCHAR2(100);',
'  l_token           VARCHAR2(32000);',
'  --',
'BEGIN',
'  -- get defaults',
'  l_mime_type := nvl(apex_application.g_x01,',
'                     ''image/png'');',
'  l_filename  := ''screenshot_'' || to_char(SYSDATE,',
'                                          ''YYYYMMDDHH24MISS'');',
'  -- file name based on mime type',
'  IF l_mime_type = ''image/png'' THEN',
'    l_filename := l_filename || ''.png'';',
'  ELSIF l_mime_type = ''image/jpeg'' THEN',
'    l_filename := l_filename || ''.jpg'';',
'  ELSIF l_mime_type = ''application/pdf'' THEN',
'    l_filename := l_filename || ''.pdf'';',
'  END IF;',
'  -- build CLOB from f01 30k Array',
'  dbms_lob.createtemporary(l_blob,',
'                           FALSE,',
'                           dbms_lob.session);',
'  FOR i IN 1 .. apex_application.g_f01.count LOOP',
'    l_token := wwv_flow.g_f01(i);',
'    IF length(l_token) > 0 THEN',
'      dbms_lob.append(l_blob,',
'                      to_blob(utl_encode.base64_decode(utl_raw.cast_to_raw(l_token))));',
'    END IF;',
'  END LOOP;',
'  --',
'  -- create own collection (here starts custom part (for example a Insert statement))',
'  -- collection name',
'  l_collection_name := ''SCREEN_CAPTURE'';',
'  -- check if exist',
'  IF NOT apex_collection.collection_exists(p_collection_name => l_collection_name) THEN',
'    apex_collection.create_collection(l_collection_name);',
'  END IF;',
'  -- add collection member (only if BLOB not null)',
'  IF dbms_lob.getlength(lob_loc => l_blob) IS NOT NULL THEN',
'    apex_collection.add_member(p_collection_name => l_collection_name,',
'                               p_c001            => l_filename, -- filename',
'                               p_c002            => l_mime_type, -- mime_type',
'                               p_d001            => SYSDATE, -- date created',
'                               p_blob001         => l_blob); -- BLOB img content',
'  END IF;',
'  --',
'END;'))
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(21002876336975434386)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'N'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT c001    AS filename,<br>',
'       c002    AS mime_type,<br>',
'       d001    AS date_created,<br>',
'       blob001 AS img_content<br>',
'  FROM apex_collections<br>',
' WHERE collection_name = ''SCREEN_CAPTURE'';'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'PLSQL code which saves the image to database tables or collections.<br>',
'Default to Collection "SCREEN_CAPTURE".<br>',
'Column c001 => filename<br>',
'Column c002 => mime_type<br>',
'Column d001 => date created<br>',
'Column blob001 => BLOB of image<br>'))
);
