 p_id=>wwv_flow_imp.id(298403568971437363)
,p_event_id=>wwv_flow_imp.id(298403528732437362)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_defaults_exist       number;',
'begin',
'   --',
'   select 1',
'   into   l_defaults_exist',
'   from   tr.project_cat',
'   where  project = :p0_project',
'   and    cat in',
'   (',
'      select cat',
'      from   tr.cat',
'      where  nvl(is_locked,''n'') = ''y''',
'   )',
'   and rownum < 2;',
'   --',
'exception',
'when no_data_found then   ',
'   --',
'   merge',
'   into  tr.project_cat t ',
'   using',
'   (',
'      select :p0_project project',
'      ,      cat',
'      ,      ''y'' in_service ',
'      from   tr.cat ',
'      where  nvl(is_locked,''n'') = ''y''',
'   ) s',
'   on',
'   (',
'      t.project = s.project ',
'      and ',
'      t.cat = s.cat',
'   )',
'   when matched then',
'      update',
'      set    in_service = ''y''',
'   when not matched then',
'      insert',
'      (project',
'      ,cat',
'      ,in_service',
'      )',
'      values',
'      (s.project',
'      ,s.cat',
'      ,''y''',
'      );  ',
'   --   ',
'end;',
''))
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
