,p_plug_template=>wwv_flow_imp.id(519878507656673771)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select a.*,',
'    substr(a.regions, 0, length(a.regions) - 1 ) as priority_region,',
'    b.job_number',
'from',
'(    ',
'    select meic_number,',
'        po_number,',
'        po_task,',
'        status,',
'        job_type_number,',
'        ingres_no,',
'        date_received,',
'        supplier,',
'        source,',
'        classification,',
'        assigned,',
'        acknowledge,',
'        priority_region1,',
'        priority_region2,',
'        priority_region3,',
'        priority_region4,',
'        priority_region5,',
'        priority_region6,',
'        no_obs,',
'        obs_accepted,',
'        obs_rejected,',
'        collection_start,',
'        collection_end,',
'        qa_processing_target,',
'        qa_processing_completed,',
'        qa_processing_name,',
'        databased,',
'        databased_name,',
'        validated,',
'        validated_name,',
'        comments,',
'        job_data_type,',
'        case when priority_region1 = ''N'' then '''' else ''1,'' end ||',
'        case when priority_region2 = ''N'' then '''' else ''2,'' end ||',
'        case when priority_region3 = ''N'' then '''' else ''3,'' end ||',
'        case when priority_region4 = ''N'' then '''' else ''4,'' end ||',
'        case when priority_region5 = ''N'' then '''' else ''5,'' end ||',
'        case when priority_region6 = ''N'' then '''' else ''6,'' end as regions',
'    from v_job_tracking',
') a',
'left join meds_processing_job b on b.meic_number = a.meic_number;'))
