,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_date  date;',
'    v_days  varchar2(5);',
'    v_cnt   number;',
'    v_add   number default 0;',
'begin',
'',
'    select count(*)',
'    into   v_cnt',
'    from   job_lookups',
'    where  rownum = 1 ',
'    and lower(type) = ''qatargetdays'';',
'',
'    if v_cnt = 1 then ',
'        select description',
'        into v_days',
'        from job_lookups',
'        where lower(type) = ''qatargetdays'';',
'',
'        if (REGEXP_LIKE(v_days, ''^[[:digit:]]+$'')) and (to_number(v_days) >= 0 ) then',
'            v_add := to_number(v_days);',
'        end if;',
'    end if;',
'',
'    v_date := sysdate + v_add;',
'',
'    if  to_char(v_date, ''fmday'') = ''saturday'' then',
'        v_date := v_date + 2;',
'    else',
'        if  to_char(v_date, ''fmday'') = ''sunday'' then',
'            v_date := v_date + 1;',
'        end if;',
'    end if;',
'',
'    return v_date;',
'end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'QA Processing Target'
,p_source=>'QA_PROCESSING_TARGET'
