'declare',
'    v_count number default 0;',
'begin',
'    if :P11_PRIORITY_REGION1 = ''Y'' then',
'        :P11_PRIORITY_REGION := ''1'';',
'    end if;',
'    if :P11_PRIORITY_REGION2 = ''Y'' then',
'        :P11_PRIORITY_REGION := :P11_PRIORITY_REGION || '':2'';',
'    end if;',
'    if :P11_PRIORITY_REGION3 = ''Y'' then',
'        :P11_PRIORITY_REGION := :P11_PRIORITY_REGION || '':3'';',
'    end if;',
'    if :P11_PRIORITY_REGION4 = ''Y'' then',
'        :P11_PRIORITY_REGION := :P11_PRIORITY_REGION || '':4'';',
'    end if;',
'    if :P11_PRIORITY_REGION5 = ''Y'' then',
'        :P11_PRIORITY_REGION := :P11_PRIORITY_REGION || '':5'';',
'    end if;',
'    if :P11_PRIORITY_REGION6 = ''Y'' then',
'        :P11_PRIORITY_REGION := :P11_PRIORITY_REGION || '':6'';',
'    end if;',
'',
'    select nvl(count(*),0)',
'    into v_count',
'    from meds_processing_job',
'    where meic_number = :P11_MEIC_NUMBER;',
'',
'    if v_count > 0 then',
'        select job_number ',
'        into :P11_JOB_NUMBER',
'        from meds_processing_job',
'        where meic_number = :P11_MEIC_NUMBER;',
'    end if;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
