'   ,      case when b.download_page_id is null then '''' else ''<a href="#"><div class="download-link fa fa-cloud-download" data-id="'' || b.download_page_id || ''"></div></a>'' end download_page_id',
'   ,      nvl(d.column_name, ''Not set'') column_name',
'   from   apex_collections a',
'   inner join medslayer b on b.label = a.c001',
'   left join medsfilter_medslayer_label c on c.medsfilter = :P200_MEDSFILTER ',
'   left join medslayer_label d on d.medslayer_label = c.medslayer_label',
'   where  a.collection_name     = ''C_LAYER''',
') d',
'order by d.label',
'/*',
'select d.* ',
',      d.medslayer as "AUDIT"',
'from',
'(',
