,p_process_name=>'Process Filter Layer Label'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P201_MEDSLAYER_LABEL is not null then ',
'    if :P201_MEDSFILTER_MEDSLAYER_LABEL is null then',
'        insert into medsfilter_medslayer_label (medsfilter, medslayer, medslayer_label)',
'        values (:P0_MEDSFILTER, :P201_MEDSLAYER, :P201_MEDSLAYER_LABEL);',
'    else',
'        update medsfilter_medslayer_label',
'        set medslayer_label = :P201_MEDSLAYER_LABEL',
'        where medsfilter_medslayer_label = :P201_MEDSFILTER_MEDSLAYER_LABEL;',
'    end if;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>96814356391886041
);
