wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33232939406398593)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get Filter Layer Label'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_cnt   number;',
'begin',
'    -- Does the filter has a label for the layer being edited ?',
'    select nvl(count(*),0)',
'    into   l_cnt',
'    from   medsfilter_medslayer_label a',
'    where  a.medsfilter = :P0_MEDSFILTER',
'    and    a.medslayer  = :P201_MEDSLAYER;',
'',
'    if l_cnt > 0 then ',
'        select a.medsfilter_medslayer_label',
'        ,      b.medslayer_label',
'        into   :P201_MEDSFILTER_MEDSLAYER_LABEL',
'        ,      :P201_MEDSLAYER_LABEL',
'        from       medsfilter_medslayer_label a',
'        inner join medslayer_label            b',
'            on b.medslayer_label = a.medslayer_label',
'        where  a.medsfilter      = :P0_MEDSFILTER',
'        and    a.medslayer       = :P201_MEDSLAYER;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>96814233001886040
);
end;
