,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l       number;',
'begin',
'   begin',
'      -- does the user have the role?',
'      select medsplayer',
'      into   l',
'      from   medsplayer',
'      where  medsrole = :p301_medsrole',
'      and    medsuser = :p301_medsuser;',
'      -- yes: remove...',
'      delete',
'      from   medsplayer',
'      where  medsplayer = l;',
'      --',
'   exception',
'   when no_data_found then',
'      -- no, so insert...',
'      insert',
'      into   medsplayer',
'      (medsrole',
'      ,medsuser',
'      )',
'      values',
'      (:p301_medsrole',
'      ,:p301_medsuser',
'      );',
'      --',
'   end; ',
'   :p301_medsrole_updated := ''y'';     ',
'end;'))
,p_attribute_02=>'P301_MEDSUSER,P301_MEDSROLE'
,p_attribute_03=>'P301_MEDSROLE_UPDATED'
,p_attribute_04=>'N'
