,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l       number;',
'begin',
'   begin',
'      -- does the user have the layer?',
'      select medsuser_medslayer',
'      into   l',
'      from   medsuser_medslayer',
'      where  medslayer = :p301_medslayer',
'      and    medsuser  = :p301_medsuser;',
'      -- yes: remove...',
'      delete',
'      from   medsuser_medslayer',
'      where  medsuser_medslayer = l;',
'      --',
'   exception',
'   when no_data_found then',
'      -- no, so insert...',
'      insert',
'      into   medsuser_medslayer',
'      (medslayer',
'      ,medsuser',
'      )',
'      values',
'      (:p301_medslayer',
'      ,:p301_medsuser',
'      );',
'      --',
'   end; ',
'end;'))
,p_attribute_02=>'P301_MEDSUSER,P301_MEDSLAYER'
,p_attribute_05=>'PLSQL'
