,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'merge',
'into   medsuser_medslayer t',
'using',
'(',
'   select :p301_medsuser medsuser',
'   ,      medslayer',
'   from   medslayer',
') s',
'on',
'(',
'   t.medsuser = s.medsuser',
'   and',
'   t.medslayer = s.medslayer',
')',
'when not matched then',
'   insert',
'   (medsuser',
'   ,medslayer',
'   )',
'   values',
'   (s.medsuser',
'   ,s.medslayer',
'   );',
''))
,p_attribute_02=>'P301_MEDSUSER'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
