prompt --application/pages/page_00322
begin
wwv_flow_imp_page.create_page(
 p_id=>322
,p_name=>'GeoTIFF upload '
,p_alias=>'GEOTIFF-UPLOAD'
,p_page_mode=>'MODAL'
,p_step_title=>'GeoTIFF upload '
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(31901452569987853)
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'https://cdn.jsdelivr.net/npm/geotiff',
'#WORKSPACE_FILES#main-dist.js',
'#WORKSPACE_FILES#proj4.js',
''))
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const { fromUrl, fromUrls, fromArrayBuffer, fromBlob } = GeoTIFF;',
'const input = document.getElementById(''P322_BLOB_CONTENT'');',
'input.onchange = async function() ',
'{',
'   console.log(''input.onchange'');',
'   const tiff = await fromBlob(input.files[0]);',
'   const image = await tiff.getImage();',
'   const width = image.getWidth();',
'   const height = image.getHeight();',
'   const tileHeight = image.getTileHeight();',
'   const samplesPerPixel = image.getSamplesPerPixel();',
'   const origin = image.getOrigin();',
'   const resolution = image.getResolution();',
'   const bounds = image.getBoundingBox();',
'   const geoKeys = image.getGeoKeys();',
'   const projObj = await geokeysToProj4.toProj4(geoKeys);',
'   const projection = await proj4(''WGS84'', projObj.proj4);',
'   var minXY = await projection.inverse([bounds[0], bounds[1]]);',
'   var maxXY = await projection.inverse([bounds[2], bounds[3]]);',
'   const bbox = [minXY[0], minXY[1], maxXY[0], maxXY[1]];',
'//',
'            // //Use a decoder pool for faster processing of GeoTiff image.',
'            // const pool = new GeoTIFF.Pool();',
'',
'            // //Load the RGB data from the GeoTiff file.',
'            // const rgb = await image.readRGB({',
'            //     pool',
'            // });',
'',
'   const rgb =  image.readRGB;',
'',
'   const canvas = document.createElement(''canvas'');',
'   canvas.width = width;',
'   canvas.height = height;',
'',
'   const ctx = canvas.getContext(''2d'');',
'   const imageData = ctx.getImageData(0, 0, width, height);',
'   const data = imageData.data;',
'',
'   let j = 0;',
'   for (let i = 0; i < rgb.length; i += 3) {',
'         data[j] = rgb[i];',
'         data[j + 1] = rgb[i + 1];',
'         data[j + 2] = rgb[i + 2];',
'         data[j + 3] = 255;',
'         j += 4;',
'   }',
'   ctx.putImageData(imageData, 0, 0);',
'   const pngUrl = canvas.toDataURL();',
'// console.log(pngUrl);',
'//',
'   // console.log(width);',
'   // console.log(height);',
'   // console.log(''tw=''+tileWidth);',
'   // console.log(''th=''+tileHeight);',
'   // console.log(samplesPerPixel);',
'   // console.log(origin);',
'   // console.log(resolution);',
'   // console.log(bbox);',
'   // console.log(geoKeys);',
'   // console.log(minXY);',
'   // console.log(maxXY);',
'//',
'   $s(''P322_WIDTH'',width);',
'   $s(''P322_HEIGHT'',height);',
'   $s(''P322_TILEWIDTH'',tileWidth);',
'   $s(''P322_TILEHEIGHT'',tileHeight);',
'   $s(''P322_SAMPLESPERPIXEL'',samplesPerPixel);',
'   $s(''P322_ORIGIN'',origin);',
'   $s(''P322_RESOLUTION'',resolution);',
'   $s(''P322_BBOX'',bounds);',
'   $s(''P322_GEOKEYS'',JSON.stringify(geoKeys));',
'   $s(''P322_MINXY'',minXY);',
'   $s(''P322_MAXXY'',maxXY);',
'   $s(''P322_BASE64'',pngUrl);',
'//',
'   $.event.trigger(''enableSubmit'');',
'}',
''))
,p_step_template=>wwv_flow_imp.id(166725501286780573)
,p_page_template_options=>'#DEFAULT#:js-dialog-class-t-Drawer--pullOutEnd:js-dialog-class-t-Drawer--xl'
,p_protection_level=>'C'
,p_page_component_map=>'17'
,p_last_updated_by=>'DANIEL'
,p_last_upd_yyyymmddhh24miss=>'20240614082109'
);
