,p_process_name=>'update'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- declare',
'--    l_clob clob := :p322_base64;',
'--    l_blob blob;',
'-- begin',
'--    --   ',
'--    -- l_blob := apex_util.clob_to_blob',
'--    --          (p_clob => l_clob',
'--    --          );',
'--    --',
'--    update geotiff',
'--    set    base64  = l_clob --l_blob',
'--    where  geotiff = :p322_geotiff;',
'--    --',
'-- END;',
'',
'',
'DECLARE',
'  l_clob clob := :p322_base64;',
'  l_blob    BLOB;',
'  l_raw     RAW(32767);',
'  l_amt     NUMBER := 7700;',
'  l_offset  NUMBER := 1;',
'  l_temp    VARCHAR2(32767);',
'BEGIN',
'  BEGIN',
'    DBMS_LOB.createtemporary (l_blob, FALSE, DBMS_LOB.CALL);',
'    LOOP',
'      DBMS_LOB.read(l_clob, l_amt, l_offset, l_temp);',
'      l_offset := l_offset + l_amt;',
'      l_raw    := UTL_ENCODE.base64_decode(UTL_RAW.cast_to_raw(l_temp));',
'      DBMS_LOB.append (l_blob, TO_BLOB(l_raw));',
'    END LOOP;',
'  EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'      NULL;',
'  END;',
'   update medsgeotiff',
'   set    base64_blob  = l_blob',
'   where  medsgeotiff = :p322_medsgeotiff;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>93148822570852921
);
