,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate Fields'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select',
'       a.data_type',
'    ,  b.job_data_type',
'    ,  b.job_type_number',
'    ,  b.status',
'    ,  b.assigned',
'    ,  b.meic_number',
'    into',
'       :P2101_DATA_TYPE',
'    ,  :P2101_JOB_DATA_TYPE',
'    ,  :P2101_JOB_TYPE_NUMBER',
'    ,  :P2101_JOB_STATUS',
'    ,  :P2101_ASSIGNED',
'    ,  :P2101_MEIC_NUMBER',
'    from meds_processing_job   a',
'    inner join job_tracking    b',
'       on b.meic_number  = a.meic_number',
'    where a.job_number   = :P2101_MEDS_JOB_NUMBER;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>82126253386339030
);
