'        return :P2111_SUPPLIER;',
'    else',
'        select ship',
'        into l_ship',
'        from   mlo_birds_data',
'        where  meds_job_number         = :P2111_MEDS_JOB_NUMBER',
'        and    meds_observation_number = :P2111_MEDS_OBSERVATION_NUMBER - 1;',
'',
'        if l_ship is null then',
