'begin',
'    if :P2111_LONGITUDE is not null and :P2111_LATITUDE is not null then ',
'        update mlo_birds_observation',
'        set location =  SDO_GEOMETRY(2001,4326,',
'                        SDO_POINT_TYPE(:P2111_LONGITUDE,:P2111_LATITUDE,NULL),NULL,NULL)',
'        where meds_job_number       = :P2111_MEDS_JOB_NUMBER_O',
'        and meds_observation_number = :P2111_MEDS_OBSERVATION_NUMBER_O;',
'    end if;',
