,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate Fields'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'    select',
'       a.data_type',
'    ,  b.job_data_type',
'    ,  b.job_type_number',
'    ,  b.status',
'    ,  b.assigned',
'    ,  b.meic_number',
'    ,  b.supplier',
'    into',
'       :P2111_DATA_TYPE',
'    ,  :P2111_JOB_DATA_TYPE',
'    ,  :P2111_JOB_TYPE_NUMBER',
'    ,  :P2111_JOB_STATUS',
'    ,  :P2111_ASSIGNED',
'    ,  :P2111_MEIC_NUMBER',
'    ,  :P2111_SUPPLIER',
'    from meds_processing_job   a',
'    inner join job_tracking    b',
'       on b.meic_number  = a.meic_number',
'    where a.job_number   = :P2111_MEDS_JOB_NUMBER;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>82250310029565993
);
