,p_item_source_plug_id=>wwv_flow_imp.id(339486389076282309)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_ship  varchar2(64);',
'begin',
'',
'    if :P2121_MEDS_OBSERVATION_NUMBER = 1 then',
'        return :P2121_SUPPLIER;',
'    else',
'        select ship',
'        into l_ship',
'        from   mlo_seabed_contact_data',
'        where  meds_job_number         = :P2121_MEDS_JOB_NUMBER',
'        and    meds_observation_number = :P2121_MEDS_OBSERVATION_NUMBER - 1;',
'',
'        if l_ship is null then',
'            return :P2121_SUPPLIER;',
'        else',
'            return l_ship;',
'        end if;',
'    end if;',
'end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'Platform'
