'declare',
'   v_return             geospatial_util.dmm_coordinate_tp;',
'   v_coordinate_type    varchar2(10);',
'begin',
'',
'    v_coordinate_type := ''LATITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2121_LATITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2121_LAT_TEXT_D := v_return.degrees;',
'    :P2121_LAT_TEXT_M := v_return.decimal_minutes;',
'    :P2121_LAT_TEXT_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2121_LONGITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2121_LONG_TEXT_D := v_return.degrees;',
'    :P2121_LONG_TEXT_M := v_return.decimal_minutes;',
'    :P2121_LONG_TEXT_C := v_return.cardinal;   ',
'end;'))
,p_attribute_02=>'P2121_LATITUDE,P2121_LONGITUDE'
,p_attribute_03=>'P2121_LAT_TEXT_D,P2121_LAT_TEXT_M,P2121_LAT_TEXT_C,P2121_LONG_TEXT_D,P2121_LONG_TEXT_M,P2121_LONG_TEXT_C'
