'    l_hi_cruise  varchar2(64);',
'begin',
'',
'    if :P2131_MEDS_OBSERVATION_NUMBER > 1 then',
'        select hi_cruise',
'        into l_hi_cruise',
'        from   deep_scattering_data',
'        where  meds_job_number         = :P2131_MEDS_JOB_NUMBER',
'        and    meds_observation_number = :P2131_MEDS_OBSERVATION_NUMBER - 1;',
'',
'        return l_hi_cruise;',
