 p_id=>wwv_flow_imp.id(19601431418275707)
,p_event_id=>wwv_flow_imp.id(19600505957275706)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_return             geospatial_util.dmm_coordinate_tp;',
'   v_coordinate_type    varchar2(10);',
'begin',
'',
'    v_coordinate_type := ''LATITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2131_LATITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2131_LAT_START_D := v_return.degrees;',
'    :P2131_LAT_START_M := v_return.decimal_minutes;',
'    :P2131_LAT_START_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2131_LONGITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2131_LONG_START_D := v_return.degrees;',
'    :P2131_LONG_START_M := v_return.decimal_minutes;',
'    :P2131_LONG_START_C := v_return.cardinal;   ',
'',
'    :P2131_LAT_END_D  := substr(:P2131_END_LAT_LONG, 1, 2);',
'    :P2131_LAT_END_M  := replace(substr(:P2131_END_LAT_LONG, 4, 6),chr(39),'''');',
'    :P2131_LAT_END_C  := substr(:P2131_END_LAT_LONG, 10, 1);',
'',
'    :P2131_LONG_END_D := substr(:P2131_END_LAT_LONG, 12, 3);',
'    :P2131_LONG_END_M := replace(substr(:P2131_END_LAT_LONG, 16, 6),chr(39),'''');',
'    :P2131_LONG_END_C := substr(:P2131_END_LAT_LONG, 22, 1);',
'',
'end;'))
,p_attribute_02=>'P2131_LATITUDE,P2131_LONGITUDE,P2131_END_LAT_LONG'
,p_attribute_03=>'P2131_LAT_START_D,P2131_LAT_START_M,P2131_LAT_START_C,P2131_LONG_START_D,P2131_LONG_START_M,P2131_LONG_START_C,P2131_LAT_END_D,P2131_LAT_END_M,P2131_LAT_END_C,P2131_LONG_END_D,P2131_LONG_END_M,P2131_LONG_END_C'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
