wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(19599608649275705)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'setNumbers'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  v_0   varchar2(50);',
'  v_1   varchar2(50);',
'  v_2   varchar2(50);',
'  v_3   varchar2(50);',
'begin ',
'    -- Observation latitude and longitude are the form start latitude and longitude',
'    :p2131_LATITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                            p_degrees         => :p2131_LAT_START_D,',
'                            p_decimal_minutes => :p2131_LAT_START_M,',
'                            p_cardinal        => :p2131_LAT_START_C',
'                        );',
'   :p2131_LONGITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                            p_degrees         => :p2131_LONG_START_D,',
'                            p_decimal_minutes => :p2131_LONG_START_M,',
'                            p_cardinal        => :p2131_LONG_START_C                            ',
'                        );',
'',
'   v_0 := trim(to_char(:p2131_lat_end_d, ''00''))       || '' '' || ',
'          trim(to_char(:p2131_lat_end_m, ''00.00''))    || ',
'          :p2131_lat_end_c                      || '' '' || ',
'          trim(to_char(:p2131_long_end_d,''000''))      || '' '' || ',
'          trim(to_char(:p2131_long_end_m, ''00.00''))   || ',
'          :p2131_long_end_c;',
'    v_1 := substr(v_0, 1, 5);',
'    v_2 := substr(v_0, 6, 11);',
'    v_3 := substr(v_0, 17);',
'',
'   --:P2131_END_LAT_LONG := v_0;  ',
'   :P2131_END_LAT_LONG := v_1 || chr(39) || v_2 || chr(39) || v_3;               ',
'   ',
'   :p2131_month := extract(month from to_date(:P2131_DATE_RECORDED));',
'',
'   :p2131_meds_observation_number_o := :p2131_meds_observation_number;',
'   :p2131_meds_observation_number_d := :p2131_meds_observation_number;',
'',
'   :p2131_meds_job_number_o := :p2131_meds_job_number;',
'   :p2131_meds_job_number_d := :p2131_meds_job_number;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,CREATE_ANOTHER,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
