,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select',
'       a.data_type',
'    ,  b.job_data_type',
'    ,  b.job_type_number',
'    ,  b.status',
'    ,  b.assigned',
'    ,  b.meic_number',
'    ,  b.supplier',
'    into',
'       :P2131_DATA_TYPE',
'    ,  :P2131_JOB_DATA_TYPE',
'    ,  :P2131_JOB_TYPE_NUMBER',
'    ,  :P2131_JOB_STATUS',
'    ,  :P2131_ASSIGNED',
'    ,  :P2131_MEIC_NUMBER',
'    ,  :P2131_SUPPLIER',
'    from meds_processing_job   a',
'    inner join job_tracking    b',
'       on b.meic_number  = a.meic_number',
'    where a.job_number   = :P2131_MEDS_JOB_NUMBER;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
