 p_id=>wwv_flow_imp.id(20248594982409561)
,p_event_id=>wwv_flow_imp.id(20247533183409558)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_return             geospatial_util.dmm_coordinate_tp;',
'   v_coordinate_type    varchar2(10);',
'begin',
'',
'    v_coordinate_type := ''LATITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2141_LATITUDE_START,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'    :P2141_LAT_START_D := v_return.degrees;',
'    :P2141_LAT_START_M := v_return.decimal_minutes;',
'    :P2141_LAT_START_C := v_return.cardinal;',
'',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2141_LATITUDE_END,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'    :P2141_LAT_END_D := v_return.degrees;',
'    :P2141_LAT_END_M := v_return.decimal_minutes;',
'    :P2141_LAT_END_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2141_LONGITUDE_START,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'    :P2141_LONG_START_D := v_return.degrees;',
'    :P2141_LONG_START_M := v_return.decimal_minutes;',
'    :P2141_LONG_START_C := v_return.cardinal;   ',
'   ',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2141_LONGITUDE_END,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'    :P2141_LONG_END_D := v_return.degrees;',
'    :P2141_LONG_END_M := v_return.decimal_minutes;',
'    :P2141_LONG_END_C := v_return.cardinal;',
'end;'))
,p_attribute_02=>'P2141_LATITUDE_START,P2141_LATITUDE_END,P2141_LONGITUDE_START,P2141_LONGITUDE_END'
,p_attribute_03=>'P2141_LAT_END_D,P2141_LAT_START_D,P2141_LAT_END_M,P2141_LAT_START_M,P2141_LAT_END_C,P2141_LAT_START_C,P2141_LONG_START_D,P2141_LONG_END_D,P2141_LONG_START_M,P2141_LONG_END_M,P2141_LONG_START_C,P2141_LONG_END_C'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
