,p_process_name=>'setNumbers'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin ',
'    :p2141_LATITUDE_START := geospatial_util.dmm_to_dd',
'                        ( ',
'                            p_degrees         => :p2141_LAT_START_D,',
'                            p_decimal_minutes => :p2141_LAT_START_M,',
'                            p_cardinal        => :p2141_LAT_START_C',
'                        );',
'    :p2141_LATITUDE_END := geospatial_util.dmm_to_dd',
'                        ( ',
'                            p_degrees         => :p2141_LAT_END_D,',
'                            p_decimal_minutes => :p2141_LAT_END_M,',
'                            p_cardinal        => :p2141_LAT_END_C                            ',
'                        );',
'    :p2141_LONGITUDE_START := geospatial_util.dmm_to_dd',
'                        ( ',
'                            p_degrees         => :p2141_LONG_START_D,',
'                            p_decimal_minutes => :p2141_LONG_START_M,',
'                            p_cardinal        => :p2141_LONG_START_C',
'                        );',
'   :p2141_LONGITUDE_END := geospatial_util.dmm_to_dd',
'                        ( ',
'                            p_degrees         => :p2141_LONG_END_D,',
'                            p_decimal_minutes => :p2141_LONG_END_M,',
'                            p_cardinal        => :p2141_LONG_END_C                            ',
'                        );',
'',
'   :p2141_meds_track_number_t   := :p2141_meds_track_number;',
'   :p2141_meds_job_number_t     := :p2141_meds_job_number;',
'   :P2141_OFFSET_END            := :P2141_VISIBILITY;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,CREATE_ANOTHER,CREATE_AND_OBS,SAVE'
