wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(20246382274409557)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'updateLocation'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_num_obs   number;',
'begin',
'    if :P2141_LONGITUDE_START is not null and :P2141_LATITUDE_START is not null and :P2141_LONGITUDE_END is not null and :P2141_LATITUDE_END is not null then ',
'        update mlo_cetaceans_track',
'        set location =  SDO_GEOMETRY(2002,4326,NULL,',
'                        SDO_ELEM_INFO_ARRAY(1,2,1),',
'                        SDO_ORDINATE_ARRAY(:P2141_LONGITUDE_START, :P2141_LATITUDE_START, :P2141_LONGITUDE_END, :P2141_LATITUDE_END))',
'        where meds_job_number = :P2141_MEDS_JOB_NUMBER_T',
'        and meds_track_number = :P2141_MEDS_TRACK_NUMBER_T;',
'    end if;',
'',
'    select count(*)',
'    into v_num_obs',
'    from mlo_cetaceans_observation',
'    where meds_job_number = :P2141_MEDS_JOB_NUMBER_T',
'    and meds_track_number = :P2141_MEDS_TRACK_NUMBER_T;',
'',
'    update mlo_cetaceans_track',
'    set num_obs = v_num_obs',
'    where meds_job_number = :P2141_MEDS_JOB_NUMBER_T',
'    and meds_track_number = :P2141_MEDS_TRACK_NUMBER_T;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,CREATE_ANOTHER,CREATE_AND_OBS,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>83827675869897004
);
