'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2142_LAT_TEXT_D := v_return.degrees;',
'    :P2142_LAT_TEXT_M := v_return.decimal_minutes;',
'    :P2142_LAT_TEXT_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
