'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2142_LONG_TEXT_D := v_return.degrees;',
'    :P2142_LONG_TEXT_M := v_return.decimal_minutes;',
'    :P2142_LONG_TEXT_C := v_return.cardinal;   ',
'end;'))
,p_attribute_02=>'P2142_LATITUDE,P2142_LONGITUDE'
,p_attribute_03=>'P2142_LAT_TEXT_D,P2142_LAT_TEXT_M,P2142_LAT_TEXT_C,P2142_LONG_TEXT_D,P2142_LONG_TEXT_M,P2142_LONG_TEXT_C'
