,p_process_name=>'setNumbers'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin ',
'   :P2142_LATITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                        p_degrees         => :P2142_LAT_TEXT_D,',
'                        p_decimal_minutes => :P2142_LAT_TEXT_M,',
'                        p_cardinal        => :P2142_LAT_TEXT_C',
'                        );',
'   :P2142_LONGITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                        p_degrees         => :P2142_LONG_TEXT_D,',
'                        p_decimal_minutes => :P2142_LONG_TEXT_M,',
'                        p_cardinal        => :P2142_LONG_TEXT_C',
'                        );',
'',
'   :p2142_month := extract(month from to_date(:P2142_DATE_RECORDED,''fmDD/MM/YYYY HH24:MI''));',
'',
'   :p2142_meds_observation_number_o := :p2142_meds_observation_number;',
'   :p2142_meds_observation_number_d := :p2142_meds_observation_number;',
'',
'   :p2142_meds_job_number_o := :p2142_meds_job_number;',
'   :p2142_meds_job_number_d := :p2142_meds_job_number;',
'',
'    select ship',
'    into :P2142_SHIP',
'    from mlo_cetaceans_track',
'    where meds_job_number = :P2142_MEDS_JOB_NUMBER',
'    and meds_track_number = :P2142_MEDS_TRACK_NUMBER;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,CREATE_ANOTHER,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>94132380504362823
);
