wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(30550612320875376)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'updateLocationAndNrObservations'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_num_obs   number;',
'begin',
'    if :P2142_LONGITUDE is not null and :P2142_LATITUDE is not null then ',
'        update mlo_cetaceans_observation',
'        set location =  SDO_GEOMETRY(2001,4326,',
'                        SDO_POINT_TYPE(:P2142_LONGITUDE,:P2142_LATITUDE,NULL),NULL,NULL)',
'        where meds_job_number       = :P2142_MEDS_JOB_NUMBER_O',
'        and meds_observation_number = :P2142_MEDS_OBSERVATION_NUMBER_O;',
'    end if;',
'',
'    select count(*)',
'    into v_num_obs',
'    from mlo_cetaceans_observation',
'    where meds_job_number = :P2142_MEDS_JOB_NUMBER_O',
'    and meds_track_number = :P2142_MEDS_TRACK_NUMBER;',
'',
'    update mlo_cetaceans_track',
'    set num_obs = v_num_obs',
'    where meds_job_number = :P2142_MEDS_JOB_NUMBER_O',
'    and meds_track_number = :P2142_MEDS_TRACK_NUMBER;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,CREATE_ANOTHER,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>94131905916362823
);
