'                        );',
'   :p2151_LONGITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                        p_degrees         => :p2151_LONG_TEXT_D,',
'                        p_decimal_minutes => :p2151_LONG_TEXT_M,',
'                        p_cardinal        => :p2151_LONG_TEXT_C',
'                        );',
'',
'   :p2151_month := extract(month from to_date(:P2151_DATE_RECORDED));',
'',
'   :p2151_meds_observation_number_o := :p2151_meds_observation_number;',
'   :p2151_meds_observation_number_d := :p2151_meds_observation_number;',
'',
'   :p2151_meds_job_number_o := :p2151_meds_job_number;',
'   :p2151_meds_job_number_d := :p2151_meds_job_number;',
'end;'))
