,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin ',
'   :p2161_LATITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                        p_degrees         => :p2161_LAT_TEXT_D,',
'                        p_decimal_minutes => :p2161_LAT_TEXT_M,',
'                        p_cardinal        => :p2161_LAT_TEXT_C',
'                        );',
'   :p2161_LONGITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                        p_degrees         => :p2161_LONG_TEXT_D,',
'                        p_decimal_minutes => :p2161_LONG_TEXT_M,',
'                        p_cardinal        => :p2161_LONG_TEXT_C',
'                        );',
'',
'   :p2161_month := extract(month from to_date(:P2161_DATE_RECORDED));',
'',
'   :p2161_meds_observation_number_o := :p2161_meds_observation_number;',
'   :p2161_meds_observation_number_d := :p2161_meds_observation_number;',
'',
'   :p2161_meds_job_number_o := :p2161_meds_job_number;',
'   :p2161_meds_job_number_d := :p2161_meds_job_number;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
