,p_process_name=>'clearNumbers'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    :p2161_meds_observation_number_o    := null;',
'    :p2161_meds_observation_number_d    := null;',
'    :p2161_meds_job_number_o            := null;',
