'declare',
'   v_return             geospatial_util.dmm_coordinate_tp;',
'   v_coordinate_type    varchar2(10);',
'begin',
'',
'    v_coordinate_type := ''LATITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2171_LATITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2171_LAT_TEXT_D := v_return.degrees;',
'    :P2171_LAT_TEXT_M := v_return.decimal_minutes;',
'    :P2171_LAT_TEXT_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2171_LONGITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2171_LONG_TEXT_D := v_return.degrees;',
'    :P2171_LONG_TEXT_M := v_return.decimal_minutes;',
'    :P2171_LONG_TEXT_C := v_return.cardinal;   ',
'end;'))
,p_attribute_02=>'P2171_LATITUDE,P2171_LONGITUDE'
,p_attribute_03=>'P2171_LAT_TEXT_D,P2171_LAT_TEXT_M,P2171_LAT_TEXT_C,P2171_LONG_TEXT_D,P2171_LONG_TEXT_M,P2171_LONG_TEXT_C'
