'                        );',
'',
'   :p2171_month := extract(month from to_date(:P2171_DATE_RECORDED));',
'',
'   :p2171_meds_observation_number_o := :p2171_meds_observation_number;',
'   :p2171_meds_observation_number_d := :p2171_meds_observation_number;',
'',
'   :p2171_meds_job_number_o := :p2171_meds_job_number;',
