,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate Fields'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select',
'       a.data_type',
'    ,  b.job_data_type',
'    ,  b.job_type_number',
'    ,  b.status',
'    ,  b.assigned',
'    ,  b.meic_number',
'    ,  b.supplier',
'    into',
'       :P2171_DATA_TYPE',
'    ,  :P2171_JOB_DATA_TYPE',
'    ,  :P2171_JOB_TYPE_NUMBER',
'    ,  :P2171_JOB_STATUS',
'    ,  :P2171_ASSIGNED',
'    ,  :P2171_MEIC_NUMBER',
'    ,  :P2171_SUPPLIER',
'    from meds_processing_job   a',
'    inner join job_tracking    b',
'       on b.meic_number  = a.meic_number',
'    where a.job_number   = :P2171_MEDS_JOB_NUMBER;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>82780870396573159
);
end;
