'        return :P2181_SUPPLIER;',
'    else',
'        select ship',
'        into l_ship',
'        from   mlo_pinnipeds_data',
'        where  meds_job_number         = :P2181_MEDS_JOB_NUMBER',
'        and    meds_observation_number = :P2181_MEDS_OBSERVATION_NUMBER - 1;',
