,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_return             geospatial_util.dmm_coordinate_tp;',
'   v_coordinate_type    varchar2(10);',
'begin',
'',
'    v_coordinate_type := ''LATITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2181_LATITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2181_LAT_TEXT_D := v_return.degrees;',
'    :P2181_LAT_TEXT_M := v_return.decimal_minutes;',
'    :P2181_LAT_TEXT_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2181_LONGITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2181_LONG_TEXT_D := v_return.degrees;',
'    :P2181_LONG_TEXT_M := v_return.decimal_minutes;',
'    :P2181_LONG_TEXT_C := v_return.cardinal;   ',
'end;'))
,p_attribute_02=>'P2181_LATITUDE,P2181_LONGITUDE'
,p_attribute_03=>'P2181_LAT_TEXT_D,P2181_LAT_TEXT_M,P2181_LAT_TEXT_C,P2181_LONG_TEXT_D,P2181_LONG_TEXT_M,P2181_LONG_TEXT_C'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
