,p_process_name=>'setNumbers'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin ',
'',
'   :p2181_LATITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                        p_degrees         => :p2181_LAT_TEXT_D,',
'                        p_decimal_minutes => :p2181_LAT_TEXT_M,',
'                        p_cardinal        => :p2181_LAT_TEXT_C',
'                        );',
'   :p2181_LONGITUDE := geospatial_util.dmm_to_dd',
'                        ( ',
'                        p_degrees         => :p2181_LONG_TEXT_D,',
'                        p_decimal_minutes => :p2181_LONG_TEXT_M,',
'                        p_cardinal        => :p2181_LONG_TEXT_C',
'                        );',
'',
'   :p2181_month := extract(month from to_date(:P2181_DATE_RECORDED));',
'',
'   :p2181_meds_observation_number_o := :p2181_meds_observation_number;',
'   :p2181_meds_observation_number_d := :p2181_meds_observation_number;',
'',
'   :p2181_meds_job_number_o := :p2181_meds_job_number;',
'   :p2181_meds_job_number_d := :p2181_meds_job_number;',
'end;'))
,p_process_clob_language=>'PLSQL'
