,p_item_source_plug_id=>wwv_flow_imp.id(339436700787085731)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_ship  varchar2(64);',
'begin',
'',
'    if :P2181_MEDS_OBSERVATION_NUMBER = 1 then',
'        return :P2181_SUPPLIER;',
'    else',
'        select ship',
'        into l_ship',
'        from   mlo_reptiles_data',
'        where  meds_job_number         = :P2181_MEDS_JOB_NUMBER',
'        and    meds_observation_number = :P2181_MEDS_OBSERVATION_NUMBER - 1;',
'',
'        if l_ship is null then',
'            return :P2181_SUPPLIER;',
'        else',
'            return l_ship;',
'        end if;',
'    end if;',
'end;'))
