'   v_coordinate_type    varchar2(10);',
'begin',
'',
'    v_coordinate_type := ''LATITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2191_LATITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2191_LAT_TEXT_D := v_return.degrees;',
'    :P2191_LAT_TEXT_M := v_return.decimal_minutes;',
'    :P2191_LAT_TEXT_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dmm',
'    (',
'      p_dd_coordinate   => :P2191_LONGITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2191_LONG_TEXT_D := v_return.degrees;',
'    :P2191_LONG_TEXT_M := v_return.decimal_minutes;',
'    :P2191_LONG_TEXT_C := v_return.cardinal;   ',
'end;'))
