,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_return             geospatial_util.dms_coordinate_tp;',
'   v_coordinate_type    varchar2(10);',
'begin',
'',
'    v_coordinate_type := ''LATITUDE'';',
'    v_return := geospatial_util.dd_to_dms',
'    (',
'      p_dd_coordinate   => :P2201_LATITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2201_LAT_TEXT_D := v_return.degrees;',
'    :P2201_LAT_TEXT_M := v_return.minutes;',
'    :P2201_LAT_TEXT_S := v_return.seconds;',
'    :P2201_LAT_TEXT_C := v_return.cardinal;',
'',
'    v_coordinate_type := ''LONGITUDE'';',
'    v_return := geospatial_util.dd_to_dms',
'    (',
'      p_dd_coordinate   => :P2201_LONGITUDE,',
'      p_coordinate_type => v_coordinate_type',
'    );',
'',
'    :P2201_LONG_TEXT_D := v_return.degrees;',
'    :P2201_LONG_TEXT_M := v_return.minutes;',
'    :P2201_LONG_TEXT_S := v_return.seconds;',
'    :P2201_LONG_TEXT_C := v_return.cardinal;   ',
'end;'))
,p_attribute_02=>'P2201_LATITUDE,P2201_LONGITUDE'
,p_attribute_03=>'P2201_LAT_TEXT_D,P2201_LAT_TEXT_M,P2201_LAT_TEXT_S,P2201_LAT_TEXT_C,P2201_LONG_TEXT_D,P2201_LONG_TEXT_M,P2201_LONG_TEXT_S,P2201_LONG_TEXT_C'
,p_attribute_04=>'Y'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
