'        update mlo_ship_observation',
'        set location =  SDO_GEOMETRY(2001,4326,',
'                        SDO_POINT_TYPE(:P2201_LONGITUDE,:P2201_LATITUDE,NULL),NULL,NULL)',
'        where meds_job_number       = :P2201_MEDS_JOB_NUMBER_O',
'        and meds_observation_number = :P2201_MEDS_OBSERVATION_NUMBER_O;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,CREATE_ANOTHER,SAVE'
