'begin',
'',
'    select',
'       a.data_type',
'    ,  b.job_data_type',
'    ,  b.job_type_number',
'    ,  b.status',
'    ,  b.assigned',
'    ,  b.meic_number',
'    ,  b.supplier',
'    into',
'       :P2201_DATA_TYPE',
'    ,  :P2201_JOB_DATA_TYPE',
'    ,  :P2201_JOB_TYPE_NUMBER',
'    ,  :P2201_JOB_STATUS',
'    ,  :P2201_ASSIGNED',
'    ,  :P2201_MEIC_NUMBER',
'    ,  :P2201_SUPPLIER',
'    from meds_processing_job   a',
'    inner join job_tracking    b',
'       on b.meic_number  = a.meic_number',
'    where a.job_number   = :P2201_MEDS_JOB_NUMBER;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
