wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(67260750320576449)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate Other Fields'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select ',
'        a.job_data_type',
'    ,   a.status',
'    ,   a.assigned',
'    ,   b.description',
'    ,   (select listagg(d.filename, '','') within group(order by d.filename) from stg_file d where d.job_number = c.job_number group by d.job_number)',
'    into  :P3001_JOB_DATA_TYPE',
'    ,     :P3001_JOB_STATUS',
'    ,     :P3001_ASSIGNED',
'    ,     :P3001_JOB_TYPE',
'    ,     :P3001_LOADED_FILES',
'    from   job_tracking a ',
'    inner join meds_job_type b ',
'    on    b.job_type_number = a.job_type_number',
'    inner join meds_processing_job c ',
'    on    c.meic_number = a.meic_number',
'    where a.meic_number = :P3001_MEIC_NUMBER;',
'',
'    if :P3001_JOB_DATA_TYPE = ''P'' then',
'        select observation_page_id',
'        ,   track_page_id',
'        into :P3001_OBSERVATIONS_PAGE_ID',
'        , :P3001_TRACK_PAGE_ID',
'        from v_manual_form_navigation',
'        where data_type_usage = :P3001_DATA_TYPE;',
'    end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>67260750320576449
);
end;
