,p_component_template_options=>'#DEFAULT#:t-Cards--animColorFill:t-Cards--3cols:t-Cards--basic'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    a.stg_file,',
'    a.filename                                as card_title,',
'    round(a.file_size / 1000, 2) || '' KB''     as card_text,',
'    case ',
'        when :P3003_JOB_DATA_TYPE = ''S'' then ',
'            ''fa fa-file-code-o'' ',
'        else ',
'            ''fa fa-file-text-o'' ',
'        end                                   as card_icon,',
