'            o_data_use_code         => o_data_use_code,',
'            o_file_code             => o_file_code',
'        );',
'',
'        upload_serd_util.update_processing_job',
'        (',
'            p_job_number            => :p3004_job_number,',
'            p_meds_ship_number      => o_meds_ship_number,',
'            p_instrument_code       => o_instrument_code,',
'            p_data_use_code         => o_data_use_code,',
'            p_file_code             => o_file_code',
'        );',
'    else',
'        upload_csv_util.parse_csv_data',
'        (',
'            p_job_number => :P3004_JOB_NUMBER',
'        );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(70717451206392903)
,p_process_success_message=>'Observations uploaded successfully.'
,p_internal_uid=>73562496645669004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(70722089222392919)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate Fields'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    a.job_data_type,',
'    a.status,',
'    a.assigned,',
'    a.job_type_number,',
'    c.job_number,',
'    c.data_type',
'into ',
'    :P3004_JOB_DATA_TYPE,',
'    :P3004_JOB_STATUS,',
'    :P3004_ASSIGNED,',
'    :P3004_JOB_TYPE_NUMBER,',
'    :P3004_JOB_NUMBER,',
'    :P3004_DATA_TYPE',
'from job_tracking a ',
'inner join meds_processing_job c on c.meic_number = a.meic_number',
'where a.meic_number = :P3004_MEIC_NUMBER;  '))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>70722089222392919
);
end;
