wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(69094098590954859)
,p_plug_name=>'Job Processing'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(519878507656673771)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with ducs',
'as',
'(',
'   select /* +materialize */',
'          description label',
'   ,      substr(description,1,instr(description,'' '')-1) v',
'   from   job_lookups',
'   where  type = ''DUC''',
')',
', files',
'as',
'(',
'   select job_number',
'   ,      listagg(filename, ''<br/>'') within group(order by filename) filename_string',
'   from   stg_file',
'   group ',
'   by     job_number',
')',
'select a.*',
',      b.job_data_type',
',      b.job_type_number',
',      c.filename_string',
',      d.cruise_name',
',      nvl(e.label,a.data_use_code) duc',
'from   meds_processing_job a',
',      job_tracking        b',
',      files               c',
',      cruise_layer        d',
',      ducs                e',
'where  b.meic_number            = a.meic_number',
'and    c.job_number (+)         = a.job_number ',
'and    d.meds_cruise_number (+) = a.meds_cruise_number',
'and    e.v                  (+) = a.data_use_code',
''))
