wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(23150873348858455)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'setFilename'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if :p0_medsfilter is null then ',
'        :p4200_filename := ''MEDS.TEMPERATURE.'' || to_char(sysdate,''yyyy.mm.dd.hh24.mi'');    ',
'    else',
'        select ''MEDS.''',
'            ||replace(label,'' '',''_'')',
'            ||''.TEMPERATURE.''',
'            ||to_char(sysdate,''yyyy.mm.dd.hh24.mi'')',
'        into   :p4200_filename',
'        from   medsfilter',
'        where  medsfilter = :p0_medsfilter;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>86732166944345902
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(30494849376189313)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DownloadSerd'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_blob      blob;',
'begin',
'    l_blob := apex_util.clob_to_blob',
'    (',
'        p_clob => download_serd_util.get_serd_file',
'        (',
'          p_medsfilter => :P0_MEDSFILTER,',
'          p_serd_type  => ''TONLY''',
'        )',
'    );',
'',
'    sys.HTP.init;',
'    sys.OWA_UTIL.mime_header(''text/plain'', FALSE, ''ISO-8859-4'');',
'    sys.HTP.p(''Content-Length: '' || length(l_blob));',
'    sys.HTP.p(''Content-Disposition: attachment; filename="'' || :P4200_FILENAME || ''.srd"'');',
'    sys.OWA_UTIL.http_header_close;',
'',
'    sys.wpg_docload.download_file(l_blob); -- it only streams blob''s',
'',
'    apex_application.stop_apex_engine;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(30493974716179902)
,p_internal_uid=>94076142971676760
);
end;
