,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DownloadSerd'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_blob      blob;',
'begin',
'    l_blob := apex_util.clob_to_blob',
'    (',
'        p_clob => download_serd_util.get_serd_file',
'        (',
'          p_medsfilter => :P0_MEDSFILTER,',
'          p_serd_type  => ''TS''',
'        )',
'    );',
'',
'    sys.HTP.init;',
'    sys.OWA_UTIL.mime_header(''text/plain'', FALSE, ''ISO-8859-4'');',
'    sys.HTP.p(''Content-Length: '' || length(l_blob));',
'    sys.HTP.p(''Content-Disposition: attachment; filename="'' || :P4201_FILENAME || ''.srd"'');',
'    sys.OWA_UTIL.http_header_close;',
'',
'    sys.wpg_docload.download_file(l_blob); -- it only streams blob''s',
'',
'    apex_application.stop_apex_engine;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(30494440367183666)
,p_internal_uid=>94076432085678374
);
