,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select a.* ',
',      a.is_cmuser color_is_cmuser',
',      nvl(a.in_service,''n'') color_in_service',
',      nvl(a.guest,''n'') color_guest  ',
',      case',
'       when a.is_cmuser = ''y'' then',
'            nvl(b.role_string_display,''?'')',
'       else',
'           ''n/a''',
'       end role_string_display         ',
',      case',
'       when a.is_cmuser = ''y'' then',
'            case',
'            when '':''||b.role_string||'':'' like ''%:MANAGER:%'' then',
'                 ''[All]''',
'            else     ',
'                  nvl(c.medsdomain_string_display,''?'')',
'            end',
'       else',
'           ''n/a''',
'       end medsdomain_string_display    ',
',      a.medsuser as "AUDIT"            ',
'from   v_medsuser                 a',
',      v_cmuser_medsrole_string   b',
',      v_cmuser_medsdomain_string c',
'where  b.cmuser (+) = a.cmuser',
'and    c.cmuser (+) = a.cmuser',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P0_TENANT'
,p_prn_page_header=>'User Management'
);
