,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l       number;',
'begin',
'   begin',
'      -- does the user have the role?',
'      select medsplayer',
'      into   l',
'      from   medsplayer',
'      where  medsrole = :p99301_medsrole',
'      and    medsuser = :p99301_medsuser;',
'      -- yes: remove...',
'      delete',
'      from   medsplayer',
'      where  medsplayer = l;',
'      --',
'   exception',
'   when no_data_found then',
'      -- no, so insert...',
'      insert',
'      into   medsplayer',
'      (medsrole',
'      ,medsuser',
'      )',
'      values',
'      (:p99301_medsrole',
'      ,:p99301_medsuser',
'      );',
'      --',
'   end; ',
'   :p99301_medsrole_updated := ''y'';     ',
'end;'))
,p_attribute_02=>'P99301_MEDSUSER,P99301_MEDSROLE'
,p_attribute_03=>'P99301_MEDSROLE_UPDATED'
