wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(21281393179217383)
,p_event_id=>wwv_flow_imp.id(21279878071217383)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'merge',
'into   medsuser_medsdomain t',
'using',
'(',
'   select :p99301_medsuser medsuser',
'   ,      medsdomain',
'   from   medsdomain',
') s',
'on',
'(',
'   t.medsuser = s.medsuser',
'   and',
'   t.medsdomain = s.medsdomain',
')',
'when not matched then',
'   insert',
'   (medsuser',
'   ,medsdomain',
'   )',
'   values',
'   (s.medsuser',
'   ,s.medsdomain',
