,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_collection_name      varchar2(30)   := ''C_LAYER'';',
'   l_layerstring          varchar2(4000);',
'   l_t                    apex_application_global.vc_arr2;',
'begin',
'   --',
'   select layerstring',
'   ,      layerstring',
'   into   :p999200_layerstring',
'   ,      l_layerstring',
'   from   medsfilter',
'   where  medsfilter = :p999200_medsfilter;',
'   --',
'   begin',
'      --',
'      select ''y''',
'      into   :p999200_can_edit',
'      from   medsfilter',
'      where  medsfilter = :p999200_medsfilter',
'      and    cmuser = :p0_cmuser;',
'      --',
'   exception',
'   when no_data_found then',
'      :p999200_can_edit := ''n'';',
'   end;',
'   --',
'   l_t := apex_string.string_to_table(l_layerstring,'':'');',
'   --',
'   apex_collection.create_or_truncate_collection',
'   (p_collection_name => l_collection_name',
'   );',
'   --',
'   for i in 1..l_t.count',
'   loop',
'      --',
'      apex_collection.add_member',
'      (p_collection_name => l_collection_name',
'      ,p_c001            => l_t(i)',
'      );',
'      --',
'   end loop;',
'   --',
'end;'))
,p_attribute_02=>'P999200_MEDSFILTER,P0_CMUSER'
,p_attribute_03=>'P999200_CAN_EDIT,P999200_LAYERSTRING'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
